public OMGTutorialInboundDataContract parmDataContract(OMGTutorialInboundDataContract _dataContract = dataContract)
{
    dataContract = _dataContract;
    return dataContract;
}

public static OMGTutorialInboundValidator newValidation(OMGTutorialInboundDataContract    _dataContract)
{
    SysDictClass                    sysDictValidationClass = new SysDictClass(_dataContract.validationClassId());
    OMGTutorialInboundValidator     inboundValidator;
    ;

    if (sysDictValidationClass)
    {
        inboundValidator = sysDictValidationClass.makeObject();
        inboundValidator.parmDataContract(_dataContract);
    }

    return inboundValidator;
}

